    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = Report{
        .pbu = "aaaaaaaa",
        .set_id = 123456,
        .report_index = 123456789,
        .biz_id = 123456,
        .exec_type = "a",
        .biz_pbu = "aaaaaaaa",
        .cl_ord_id = "aaaaaaaaaa",
        .security_id = "aaaaaaaaaaaa",
        .account = "aaaaaaaaaaaaa",
        .owner_type = 42,
        .order_entry_time = 123456789,
        .last_px = -123456789,
        .last_qty = -123456789,
        .gross_trade_amt = -123456789,
        .side = "a",
        .order_qty = -123456789,
        .leaves_qty = -123456789,
        .ord_status = "a",
        .credit_tag = "aa",
        .clearing_firm = "aaaaaaaa",
        .branch_id = "aaaaaaaa",
        .trd_cnfm_id = "aaaaaaaaaaaaaaaa",
        .ord_cnfm_id = "aaaaaaaaaaaaaaaa",
        .trade_date = 123456,
        .transact_time = 123456789,
        .user_info = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try Report.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    try std.testing.expect(msg.eql(decoded));
}
